const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a rough polygon for the Central Valley of California.
  // This polygon covers the main agricultural areas and captures the general region.
  const centralValley = ee.Geometry.Polygon([
    [-122.5, 38.8],
    [-120.7, 39.9],
    [-119.0, 38.5],
    [-118.8, 36.1],
    [-119.9, 34.9],
    [-121.7, 36.2],
    [-122.8, 37.5],
    [-122.5, 38.8]
  ]);

  const scale = 50000; // GRACE-FO data has a coarse resolution (approx. 300km)

  // 2. Data Acquisition & Check for October 2022
  const oct2022_start = '2022-10-01';
  const oct2022_end = '2022-10-31';

  let oct2022_collection = ee.ImageCollection('NASA/GRACE/GRACETWIN_GWS_M')
    .filterDate(oct2022_start, oct2022_end)
    .filterBounds(centralValley);

  let oct2022_size = await oct2022_collection.size().getInfo();
  if (oct2022_size === 0) {
    console.log("No GRACE-FO data found for October 2022.");
    console.log("C1");
    return;
  }
  let oct2022_image = oct2022_collection.first();

  // 3. Data Acquisition & Check for March 2023
  const mar2023_start = '2023-03-01';
  const mar2023_end = '2023-03-31';

  let mar2023_collection = ee.ImageCollection('NASA/GRACE/GRACETWIN_GWS_M')
    .filterDate(mar2023_start, mar2023_end)
    .filterBounds(centralValley);

  let mar2023_size = await mar2023_collection.size().getInfo();
  if (mar2023_size === 0) {
    console.log("No GRACE-FO data found for March 2023.");
    console.log("C1");
    return;
  }
  let mar2023_image = mar2023_collection.first();

  // 4. Processing and Calculation
  // Calculate the mean 'gws' (groundwater storage) for each period.
  // gws unit is meters.

  let oct2022_gws_mean = await oct2022_image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: scale,
    maxPixels: 1e9
  }).get('gws').getInfo();

  let mar2023_gws_mean = await mar2023_image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: scale,
    maxPixels: 1e9
  }).get('gws').getInfo();

  // 5. Validation & Final Answer
  if (oct2022_gws_mean === null || isNaN(oct2022_gws_mean)) {
    console.log("Calculation failed for October 2022 (result is null/NaN).");
    console.log("C3");
    return;
  }
  if (mar2023_gws_mean === null || isNaN(mar2023_gws_mean)) {
    console.log("Calculation failed for March 2023 (result is null/NaN).");
    console.log("C3");
    return;
  }

  console.log(`October 2022 (Mean GWS): ${oct2022_gws_mean.toFixed(3)} m`);
  console.log(`March 2023 (Mean GWS): ${mar2023_gws_mean.toFixed(3)} m`);

  if (oct2022_gws_mean > mar2023_gws_mean) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
